std::uint32_t next_codepoint(std::string_view text, std::size_t *index)
{
    const auto byte = [&](std::size_t at) { return static_cast<unsigned char>(text[at]); };
    const std::size_t i = *index;
    const unsigned char lead = byte(i);
    int length = 1;
    std::uint32_t value = lead;
    if (lead >= 0xf0 && lead < 0xf8)
    {
        length = 4;
        value = lead & 0x07u;
    }
    else if (lead >= 0xe0)
    {
        length = 3;
        value = lead & 0x0fu;
    }
    else if (lead >= 0xc0)
    {
        length = 2;
        value = lead & 0x1fu;
    }
    else if (lead >= 0x80)
    {
        *index = i + 1;
        return 0xfffd;
    }
    if (i + static_cast<std::size_t>(length) > text.size())
    {
        *index = text.size();
        return 0xfffd;
    }
    for (int k = 1; k < length; ++k)
    {
        const unsigned char continuation = byte(i + static_cast<std::size_t>(k));
        if ((continuation & 0xc0u) != 0x80u)
        {
            *index = i + 1;
            return 0xfffd;
        }
        value = (value << 6) | (continuation & 0x3fu);
    }
    *index = i + static_cast<std::size_t>(length);
    return value;
}

bool Font::load(std::string_view data)
{
    error_.clear();
    if (data.size() < sizeof(ff::Header))
    {
        error_ = "font too small";
        return false;
    }
    std::memcpy(&header_, data.data(), sizeof(header_));
    if (header_.magic != ff::kMagic || header_.version != ff::kVersion ||
        header_.pixel_size <= 0.0f)
    {
        error_ = "not a huifont v1";
        return false;
    }
    const std::size_t glyph_bytes =
        static_cast<std::size_t>(header_.glyph_count) * sizeof(ff::Glyph);
    const std::size_t kern_bytes = static_cast<std::size_t>(header_.kern_count) * sizeof(ff::Kern);
    const std::size_t atlas_bytes = static_cast<std::size_t>(header_.atlas_width) *
                                    static_cast<std::size_t>(header_.atlas_height);
    if (data.size() != sizeof(ff::Header) + glyph_bytes + kern_bytes + atlas_bytes)
    {
        error_ = "font size mismatch";
        return false;
    }
    const char *cursor = data.data() + sizeof(ff::Header);
    // A font may have no glyphs or (monospaced faces) no kerning pairs.
    glyphs_.resize(header_.glyph_count);
    if (glyph_bytes != 0)
        std::memcpy(glyphs_.data(), cursor, glyph_bytes);
    cursor += glyph_bytes;
    kerns_.resize(header_.kern_count);
    if (kern_bytes != 0)
        std::memcpy(kerns_.data(), cursor, kern_bytes);
    cursor += kern_bytes;
    atlas_.assign(reinterpret_cast<const std::uint8_t *>(cursor),
                  reinterpret_cast<const std::uint8_t *>(cursor) + atlas_bytes);
    for (const ff::Glyph &glyph : glyphs_)
    {
        if (glyph.x + glyph.w > header_.atlas_width || glyph.y + glyph.h > header_.atlas_height)
        {
            error_ = "glyph outside atlas";
            return false;
        }
    }
    return true;
}

const ff::Glyph *Font::find(std::uint32_t codepoint) const
{
    const auto search = [&]() -> const ff::Glyph * {
        const auto it =
            std::lower_bound(glyphs_.begin(), glyphs_.end(), codepoint,
                             [](const ff::Glyph &g, std::uint32_t c) { return g.codepoint < c; });
        return it != glyphs_.end() && it->codepoint == codepoint ? &*it : nullptr;
    };
    if (const ff::Glyph *found = search())
        return found;
    // MODIFIED for Stremio for PS5: draw the glyph now.
    return source_ != nullptr && add_glyph(codepoint) ? search() : nullptr;
}

void Font::init_dynamic(GlyphSource *source, float pixel_size, float sdf_range, float ascent, float descent,
                        float line_gap, int atlas_size)
{
    source_ = source;
    header_ = {};
    header_.magic = ff::kMagic;
    header_.version = ff::kVersion;
    header_.atlas_width = static_cast<std::uint16_t>(atlas_size);
    header_.atlas_height = static_cast<std::uint16_t>(atlas_size);
    header_.pixel_size = pixel_size;
    header_.sdf_range = sdf_range;
    header_.ascent = ascent;
    header_.descent = descent;
    header_.line_gap = line_gap;
    glyphs_.clear();
    kerns_.clear();
    atlas_.assign(static_cast<std::size_t>(atlas_size) * static_cast<std::size_t>(atlas_size), 0);
    missing_.clear();
    pen_x_ = pen_y_ = 1;
    shelf_ = 0;
    dirty_first_ = dirty_last_ = -1;
}

bool Font::add_glyph(std::uint32_t codepoint) const
{
    if (missing_.count(codepoint) != 0)
        return false;
    GlyphBitmap bitmap;
    if (!source_->glyph(codepoint, bitmap))
    {
        missing_.insert(codepoint);
        return false;
    }
    ff::Glyph record{};
    record.codepoint = codepoint;
    record.offset_x = bitmap.offset_x;
    record.offset_y = bitmap.offset_y;
    record.advance = bitmap.advance;
    if (bitmap.w > 0 && bitmap.h > 0)
    {
        const int width = header_.atlas_width;
        const int height = header_.atlas_height;
        // Shelf packing, one pixel of space around each glyph.
        if (pen_x_ + bitmap.w + 1 > width)
        {
            pen_x_ = 1;
            pen_y_ += shelf_ + 1;
            shelf_ = 0;
        }
        if (pen_y_ + bitmap.h + 1 > height)
        {
            missing_.insert(codepoint); // the atlas is full
            return false;
        }
        for (int row = 0; row < bitmap.h; ++row)
            std::memcpy(&atlas_[static_cast<std::size_t>((pen_y_ + row) * width + pen_x_)],
                        bitmap.pixels.data() + static_cast<std::size_t>(row * bitmap.w),
                        static_cast<std::size_t>(bitmap.w));
        record.x = static_cast<std::uint16_t>(pen_x_);
        record.y = static_cast<std::uint16_t>(pen_y_);
        record.w = static_cast<std::uint16_t>(bitmap.w);
        record.h = static_cast<std::uint16_t>(bitmap.h);
        dirty_first_ = dirty_first_ < 0 ? pen_y_ : std::min(dirty_first_, pen_y_);
        dirty_last_ = std::max(dirty_last_, pen_y_ + bitmap.h - 1);
        pen_x_ += bitmap.w + 1;
        shelf_ = std::max(shelf_, bitmap.h);
    }
    const auto at = std::lower_bound(glyphs_.begin(), glyphs_.end(), codepoint,
                                     [](const ff::Glyph &g, std::uint32_t c) { return g.codepoint < c; });
    glyphs_.insert(at, record);
    return true;
}

// MODIFIED for Stremio for PS5: registers a Thai variant glyph (rasterized by
// glyph index from the Thai face) under a private-use codepoint.
bool Font::add_thai_variant(std::uint32_t codepoint, int glyph_index) const
{
    if (missing_.count(codepoint) != 0)
        return false;
    GlyphBitmap bitmap;
    if (source_ == nullptr || !source_->glyph_by_index(glyph_index, bitmap))
    {
        missing_.insert(codepoint);
        return false;
    }
    ff::Glyph record{};
    record.codepoint = codepoint;
    record.offset_x = bitmap.offset_x;
    record.offset_y = bitmap.offset_y;
    record.advance = 0.0f; // marks take no advance
    if (bitmap.w > 0 && bitmap.h > 0)
    {
        const int width = header_.atlas_width;
        const int height = header_.atlas_height;
        if (pen_x_ + bitmap.w + 1 > width)
        {
            pen_x_ = 1;
            pen_y_ += shelf_ + 1;
            shelf_ = 0;
        }
        if (pen_y_ + bitmap.h + 1 > height)
        {
            missing_.insert(codepoint);
            return false;
        }
        for (int row = 0; row < bitmap.h; ++row)
            std::memcpy(&atlas_[static_cast<std::size_t>((pen_y_ + row) * width + pen_x_)],
                        bitmap.pixels.data() + static_cast<std::size_t>(row * bitmap.w),
                        static_cast<std::size_t>(bitmap.w));
        record.x = static_cast<std::uint16_t>(pen_x_);
        record.y = static_cast<std::uint16_t>(pen_y_);
        record.w = static_cast<std::uint16_t>(bitmap.w);
        record.h = static_cast<std::uint16_t>(bitmap.h);
        dirty_first_ = dirty_first_ < 0 ? pen_y_ : std::min(dirty_first_, pen_y_);
        dirty_last_ = std::max(dirty_last_, pen_y_ + bitmap.h - 1);
        pen_x_ += bitmap.w + 1;
        shelf_ = std::max(shelf_, bitmap.h);
    }
    const auto at = std::lower_bound(glyphs_.begin(), glyphs_.end(), codepoint,
                                     [](const ff::Glyph &g, std::uint32_t c) { return g.codepoint < c; });
    glyphs_.insert(at, record);
    return true;
}

namespace
{

// MODIFIED for Stremio for PS5: Thai anchor table lookups (linear; tiny).
const ta::ThaiMarkPos *thai_find_mark(const ta::ThaiAnchorSet *s, std::uint32_t cp)
{
    for (int i = 0; i < s->n_marks; ++i)
        if (s->marks[i].cp == cp)
            return &s->marks[i];
    return nullptr;
}
const ta::ThaiNarrowMark *thai_find_narrow(const ta::ThaiAnchorSet *s, std::uint32_t cp)
{
    for (int i = 0; i < s->n_narrow; ++i)
        if (s->narrow[i].cp == cp)
            return &s->narrow[i];
    return nullptr;
}
const ta::ThaiBasePos *thai_find_base(const ta::ThaiAnchorSet *s, std::uint32_t cp)
{
    for (int i = 0; i < s->n_bases; ++i)
        if (s->bases[i].cp == cp)
            return &s->bases[i];
    return nullptr;
}
const ta::ThaiStacked *thai_find_stacked(const ta::ThaiAnchorSet *s, std::uint32_t vowel, std::uint32_t tone,
                                         bool narrow_vowel)
{
    for (int i = 0; i < s->n_stacked; ++i)
    {
        const ta::ThaiStacked &st = s->stacked[i];
        if (st.vowel_cp == vowel && st.tone_cp == tone && (st.narrow_vowel != 0) == narrow_vowel)
            return &st;
    }
    return nullptr;
}
bool thai_is_narrow_base(std::uint32_t cp)
{
    for (std::uint32_t n : ta::kNarrowBases)
        if (n == cp)
            return true;
    return false;
}
// PUA codepoints for Thai variant glyphs (registered by the app at startup).
// .small tones: U+E000 + (tone - 0x0E48); .narrow marks: U+E010 + table index.
constexpr std::uint32_t kThaiSmallPua(std::uint32_t tone_cp)
{
    return 0xE000u + (tone_cp - 0x0E48u);
}
constexpr std::uint32_t kThaiNarrowPuaBase = 0xE010u;

} // namespace

bool Font::take_dirty(int *first_row, int *last_row) const
{
    if (dirty_first_ < 0)
        return false;
    *first_row = dirty_first_;
    *last_row = dirty_last_;
    dirty_first_ = dirty_last_ = -1;
    return true;
}

float Font::kern(std::uint32_t first, std::uint32_t second) const
{
    const auto it = std::lower_bound(
        kerns_.begin(), kerns_.end(), std::make_pair(first, second),
        [](const ff::Kern &k, const std::pair<std::uint32_t, std::uint32_t> &key)
        { return k.first != key.first ? k.first < key.first : k.second < key.second; });
    return it != kerns_.end() && it->first == first && it->second == second ? it->amount : 0.0f;
}

std::string Font::fit(std::string_view text, float size, float max_width, float tracking) const
{
    if (measure(text, size, tracking) <= max_width)
        return std::string(text);
    constexpr std::string_view kEllipsis = "\xE2\x80\xA6";
    const std::string_view mark = has_glyph(0x2026) ? kEllipsis : std::string_view("...");
    std::string best;
    for (std::size_t index = 0; index < text.size();)
    {
        const std::size_t start = index;
        next_codepoint(text, &index);
        std::string candidate(text.substr(0, start));
        while (!candidate.empty() && candidate.back() == ' ')
            candidate.pop_back();
        candidate.append(mark);
        if (measure(candidate, size, tracking) > max_width)
            break;
        best = std::move(candidate);
    }
    return best;
}

float Font::measure(std::string_view text, float size, float tracking) const
{
    if (transform_ != nullptr)
    {
        const std::string shaped = transform_(text);
        return measure_raw(shaped, size, tracking);
    }
    return measure_raw(text, size, tracking);
}

float Font::measure_raw(std::string_view text, float size, float tracking) const
{
    const float scale = size / header_.pixel_size;
    float width = 0.0f;
    std::uint32_t previous = 0;
    int glyphs = 0;
    for (std::size_t index = 0; index < text.size();)
    {
        std::uint32_t codepoint = next_codepoint(text, &index);
        const ff::Glyph *glyph = find(codepoint);
        if (glyph == nullptr)
        {
            codepoint = '?';
            glyph = find(codepoint);
            if (glyph == nullptr)
                continue;
        }
        if (previous != 0)
            width += kern(previous, codepoint) * scale;
        width += glyph->advance * scale;
        previous = codepoint;
        ++glyphs;
    }
    return glyphs > 1 ? width + tracking * static_cast<float>(glyphs - 1) : width;
}

float Font::layout(std::string_view text, float x, float y, float size, Align align,
                   std::vector<GlyphQuad> &quads, float tracking) const
{
    // MODIFIED for Stremio for PS5: reorder right-to-left text first.
    std::string shaped;
    if (transform_ != nullptr)
    {
        shaped = transform_(text);
        text = shaped;
    }
    const float scale = size / header_.pixel_size;
    const float width = measure_raw(text, size, tracking);
    float pen = x;
    if (align == Align::center)
        pen -= width * 0.5f;
    else if (align == Align::right)
        pen -= width;
    const float inverse_w = 1.0f / static_cast<float>(header_.atlas_width);
    const float inverse_h = 1.0f / static_cast<float>(header_.atlas_height);
    std::uint32_t previous = 0;
    // MODIFIED for Stremio for PS5: Thai combining marks. Two paths:
    // (1) Anchor path (thai_anchors_ set): positions marks with the font's
    //     own GPOS data — MarkToBase anchors for marks on consonants
    //     (.narrow variants on ป/ฝ/ฟ), and HarfBuzz-measured offsets with
    //     .small variants for stacked tones. This is what professional
    //     shapers do; the tables are baked offline by extract_anchors.py.
    // (2) Fallback heuristic (no tables): center over the base advance and
    //     stack with a gap. Used when Thai fonts didn't load.
    const float sdf_pad = sdf_range(size);
    const float thai_d2l = size / 1000.0f; // font design units -> px (upm=1000)
    bool thai_cluster = false;
    std::uint32_t thai_base_cp = 0;
    float thai_base_pen = 0.0f; // pen x at the cluster base consonant
    std::uint32_t thai_prev_mark = 0; // previous mark cp in this cluster (0 = none)
    float thai_prev_pen_x = 0.0f;
    float thai_prev_pen_y = 0.0f;
    bool thai_prev_narrow = false;
    // Fallback heuristic state (path 2).
    float thai_advance = 0.0f;
    bool thai_had_mark = false;
    bool thai_mark_above = false;
    float thai_ink_top = 0.0f;
    float thai_ink_bottom = 0.0f;
    for (std::size_t index = 0; index < text.size();)
    {
        std::uint32_t codepoint = next_codepoint(text, &index);
        const ff::Glyph *glyph = find(codepoint);
        if (glyph == nullptr)
        {
            codepoint = '?';
            glyph = find(codepoint);
            if (glyph == nullptr)
                continue;
        }
        const bool thai_mark = codepoint == 0x0e31 || (codepoint >= 0x0e34 && codepoint <= 0x0e3a) ||
                               (codepoint >= 0x0e47 && codepoint <= 0x0e4e);
        const bool thai_above = codepoint == 0x0e31 || (codepoint >= 0x0e34 && codepoint <= 0x0e37) ||
                                (codepoint >= 0x0e47 && codepoint <= 0x0e4e);
        const bool thai_base = !thai_mark && codepoint >= 0x0e00 && codepoint <= 0x0e7f;
        if (previous != 0)
            pen += kern(previous, codepoint) * scale;
        const float base_pen = pen;
        float draw_pen = pen;
        float y_shift = 0.0f;
        // The glyph actually rasterized (a .small/.narrow variant for Thai).
        std::uint32_t glyph_cp = codepoint;
        if (thai_mark && thai_cluster && thai_anchors_ != nullptr)
        {
            // Path 1: anchor positioning.
            const ta::ThaiStacked *st = thai_prev_mark != 0
                                            ? thai_find_stacked(thai_anchors_, thai_prev_mark, codepoint,
                                                               thai_prev_narrow)
                                            : nullptr;
            if (st != nullptr)
            {
                // Stacked tone: .small variant, HarfBuzz-measured offset from
                // the vowel's pen (design units, y-down).
                glyph_cp = kThaiSmallPua(codepoint);
                draw_pen = thai_prev_pen_x + static_cast<float>(st->dx) * thai_d2l;
                y_shift = (thai_prev_pen_y + static_cast<float>(st->dy) * thai_d2l) - y;
            }
            else
            {
                // MarkToBase: possibly a .narrow variant on ป/ฝ/ฟ.
                const ta::ThaiMarkPos *ma = thai_find_mark(thai_anchors_, codepoint);
                const ta::ThaiBasePos *ba = thai_find_base(thai_anchors_, thai_base_cp);
                const ta::ThaiNarrowMark *nm = nullptr;
                int narrow_idx = -1;
                if (thai_is_narrow_base(thai_base_cp) && thai_above)
                {
                    for (int i = 0; i < thai_anchors_->n_narrow; ++i)
                        if (thai_anchors_->narrow[i].cp == codepoint)
                        {
                            nm = &thai_anchors_->narrow[i];
                            narrow_idx = i;
                            break;
                        }
                }
                if (ma != nullptr && ba != nullptr)
                {
                    float ax = ma->ax, ay = ma->ay;
                    std::uint8_t cls = ma->cls;
                    if (nm != nullptr)
                    {
                        glyph_cp = kThaiNarrowPuaBase + static_cast<std::uint32_t>(narrow_idx);
                        ax = nm->ax;
                        ay = nm->ay;
                        cls = nm->cls;
                    }
                    draw_pen = thai_base_pen + (static_cast<float>(ba->x[cls]) - ax) * thai_d2l;
                    y_shift = -(static_cast<float>(ba->y[cls]) - ay) * thai_d2l;
                }
            }
            const ff::Glyph *vg = find(glyph_cp);
            if (vg != nullptr)
                glyph = vg;
            // else: variant not registered; fall through with the base glyph
            // and the anchor-computed position.
        }
        else if (thai_mark && thai_cluster)
        {
            // Path 2: fallback heuristic (no anchor tables).
            // Center the mark's bitmap over the base consonant's advance.
            draw_pen = thai_base_pen + (thai_advance - static_cast<float>(glyph->w) * scale) * 0.5f -
                       glyph->offset_x * scale;
            if (thai_had_mark && thai_above == thai_mark_above)
            {
                const float outline_r = std::max(2.0f, size * 0.055f);
                const float gap = size * 0.05f + 2.0f * outline_r;
                const float mark_h = static_cast<float>(glyph->h) * scale;
                const float default_y0 = y + glyph->offset_y * scale;
                const float default_ink_edge =
                    thai_above ? default_y0 + mark_h - sdf_pad : default_y0 + sdf_pad;
                const float want_ink_edge = thai_above ? thai_ink_top - gap : thai_ink_bottom + gap;
                y_shift = want_ink_edge - default_ink_edge;
            }
        }
        if (glyph->w > 0 && glyph->h > 0)
        {
            GlyphQuad quad;
            quad.x0 = draw_pen + glyph->offset_x * scale;
            quad.y0 = y + glyph->offset_y * scale + y_shift;
            quad.x1 = quad.x0 + static_cast<float>(glyph->w) * scale;
            quad.y1 = quad.y0 + static_cast<float>(glyph->h) * scale;
            quad.u0 = static_cast<float>(glyph->x) * inverse_w;
            quad.v0 = static_cast<float>(glyph->y) * inverse_h;
            quad.u1 = static_cast<float>(glyph->x + glyph->w) * inverse_w;
            quad.v1 = static_cast<float>(glyph->y + glyph->h) * inverse_h;
            quads.push_back(quad);
            if (thai_mark && thai_cluster)
            {
                // Remember this mark's pen for stacking the next one.
                // (glyph_cp is the original codepoint here; variants share it.)
                thai_prev_mark = codepoint;
                thai_prev_pen_x = draw_pen;
                thai_prev_pen_y = y + y_shift;
                thai_prev_narrow = glyph_cp >= kThaiNarrowPuaBase;
                if (thai_anchors_ == nullptr)
                {
                    thai_had_mark = true;
                    thai_mark_above = thai_above;
                    thai_ink_top = quad.y0 + sdf_pad;
                    thai_ink_bottom = quad.y1 - sdf_pad;
                }
            }
        }
        pen += glyph->advance * scale + tracking;
        if (thai_base)
        {
            thai_cluster = true;
            thai_base_cp = codepoint;
            thai_base_pen = base_pen;
            thai_prev_mark = 0;
            thai_prev_narrow = false;
            thai_advance = glyph->advance * scale;
            thai_had_mark = false;
        }
        else if (!thai_mark)
        {
            thai_cluster = false;
        }
        previous = codepoint;
    }
    return width;
}

std::vector<std::string> Font::wrap(std::string_view text, float size, float max_width) const
{
    std::vector<std::string> lines;
    std::string line;
    std::size_t index = 0;
    while (index <= text.size())
    {
        const std::size_t newline = text.find('\n', index);
        const std::string_view paragraph = text.substr(
            index, newline == std::string_view::npos ? std::string_view::npos : newline - index);
        std::size_t word_start = 0;
        line.clear();
        while (word_start <= paragraph.size())
        {
            std::size_t word_end = paragraph.find(' ', word_start);
            if (word_end == std::string_view::npos)
                word_end = paragraph.size();
            const std::string_view word = paragraph.substr(word_start, word_end - word_start);
            const std::string candidate =
                line.empty() ? std::string(word) : line + " " + std::string(word);
            if (!line.empty() && measure(candidate, size) > max_width)
            {
                lines.push_back(line);
                line.assign(word);
            }
            else
            {
                line = candidate;
            }
            word_start = word_end + 1;
        }
        lines.push_back(line);
        if (newline == std::string_view::npos)
            break;
        index = newline + 1;
    }
    return lines;
}

